{
  "analysis": "CSS file created successfully. Now I need to create the main visualization.js file that will load the data, create the bubble chart with force simulation, create the data table, and handle the interactions between them.",
  "plan": "Create the visualization.js file with:
1. Data loading and parsing
2. Bubble chart with force simulation (forceX/forceY for sector clustering, forceCollide for no overlap)
3. Color scale by sector with legend
4. Bubble sizing by market cap
5. Data table with all 50 stocks
6. Click interactions to highlight/select between chart and table
7. Tooltip on hover",
  "commands": [
    {
      "keystrokes": "cat > /root/output/js/visualization.js << 'ENDOFFILE'
// Stock Visualization Dashboard

// Dimensions
const width = 600;
const height = 550;
const margin = { top: 20, right: 20, bottom: 20, left: 20 };

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return 'N/A';
    const num = parseFloat(value);
    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    return num.toFixed(2);
}

// Color scale for sectors
const sectorColors = d3.scaleOrdinal(d3.schemeTableau10);

// Global state
let selectedTicker = null;
let stockData = [];

// Load and process data
d3.csv('data/stock-descriptions.csv').then(data => {
    // Process the data
    stockData = data.map(d => ({
        ticker: d.ticker,
        sector: d.sector || 'ETF',
        name: d['full name'],
        marketCap: parseFloat(d.marketCap) || 0,
        country: d.country,
        website: d.website,
        isETF: d.sector === 'ETF' || !d.sector || d.sector === ''
    }));

    // Get unique sectors for coloring
    const sectors = [...new Set(stockData.map(d => d.sector))].sort();
    sectorColors.domain(sectors);

    // Create visualizations
    createBubbleChart(stockData, sectors);
    createDataTable(stockData);
    createLegend(sectors);
});

function createBubbleChart(data, sectors) {
    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    const chartArea = svg.append('g')
        .attr('transform', `translate(${margin.left}, ${margin.top})`);

    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // Scale for bubble size based on market cap
    const maxMarketCap = d3.max(data, d => d.marketCap) || 1;
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxMarketCap])
        .range([8, 45]);

    // Calculate sector centers for clustering
    const sectorCenters = {};
    const numSectors = sectors.length;
    const cols = Math.ceil(Math.sqrt(numSectors));
    const rows = Math.ceil(numSectors / cols);
    const cellWidth = innerWidth / cols;
    const cellHeight = innerHeight / rows;

    sectors.forEach((sector, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        sectorCenters[sector] = {
            x: cellWidth * (col + 0.5),
            y: cellHeight * (row + 0.5)
        };
    });

    // Create nodes with initial positions
    const nodes = data.map(d => ({
        ...d,
        radius: d.isETF ? 12 : radiusScale(d.marketCap),
        x: sectorCenters[d.sector]?.x + (Math.random() - 0.5) * 50 || innerWidth / 2,
        y: sectorCenters[d.sector]?.y + (Math.random() - 0.5) * 50 || innerHeight / 2
    }));

    // Create force simulation
    const simulation = d3.forceSimulation(nodes)
        .force('x', d3.forceX(d => sectorCenters[d.sector]?.x || innerWidth / 2).strength(0.3))
        .force('y', d3.forceY(d => sectorCenters[d.sector]?.y || innerHeight / 2).strength(0.3))
        .force('collide', d3.forceCollide(d => d.radius + 2).strength(1))
        .force('center', d3.forceCenter(innerWidth / 2, innerHeight / 2).strength(0.05));

    // Create bubble groups
    const bubbleGroups = chartArea.selectAll('.bubble-group')
        .data(nodes)
        .enter()
        .append('g')
        .attr('class', 'bubble-group');

    // Create bubbles
    const bubbles = bubbleGroups.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors(d.sector))
        .attr('stroke', '#fff')
        .attr('stroke-width', 1.5)
        .attr('data-ticker', d => d.ticker);

    // Add labels
    const labels = bubbleGroups.append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius * 0.6, 12) + 'px');

    // Tooltip
    const tooltip = d3.select('#tooltip');

    // Bubble interactions
    bubbles
        .on('mouseover', function(event, d) {
            if (!d.isETF) {
                tooltip
                    .html(`<strong>${d.ticker}</strong>
                           <div>${d.name}</div>
                           <div>Sector: ${d.sector}</div>
                           <div>Market Cap: ${formatMarketCap(d.marketCap)}</div>`)
                    .style('left', (event.pageX + 15) + 'px')
                    .style('top', (event.pageY - 10) + 'px')
                    .classed('visible', true);
            }
        })
        .on('mousemove', function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style('left', (event.pageX + 15) + 'px')
                    .style('top', (event.pageY - 10) + 'px');
            }
        })
        .on('mouseout', function() {
            tooltip.classed('visible', false);
        })
